using ElitePos.LocalService.Services;
using ElitePos.LocalService.Models;
namespace ElitePos.LocalService.Endpoints;
public static class PartnerEndpoints
{
 private static async Task<IResult> Save(int? id,PartnerWriteRequest request,PartnerService service,CancellationToken ct){try{return id.HasValue?Results.Ok(await service.SaveAsync(id,request,ct)):Results.Created("/api/partners",await service.SaveAsync(null,request,ct));}catch(ArgumentException ex){return Results.ValidationProblem(new Dictionary<string,string[]>{{"partner",new[]{ex.Message}}});}}
 public static IEndpointRouteBuilder MapPartnerEndpoints(this IEndpointRouteBuilder endpoints){var group=endpoints.MapGroup("/api/partners");group.MapGet("",async(PartnerService service,CancellationToken ct)=>Results.Ok(await service.GetAsync(ct)));group.MapGet("/options",async(PartnerService service,CancellationToken ct)=>Results.Ok(await service.GetOptionsAsync(ct)));group.MapGet("/{publicId:guid}",async(Guid publicId,PartnerService service,CancellationToken ct)=>{var item=await service.GetAsync(publicId,ct);return item is null?Results.NotFound():Results.Ok(item);});group.MapPost("",(PartnerWriteRequest request,PartnerService service,CancellationToken ct)=>Save(null,request,service,ct));group.MapPut("/by-public/{publicId:guid}",async(Guid publicId,PartnerWriteRequest request,PartnerService service,CancellationToken ct)=>{try{return Results.Ok(await service.SaveByPublicIdAsync(publicId,request,ct));}catch(ArgumentException ex){return Results.ValidationProblem(new Dictionary<string,string[]>{{"partner",new[]{ex.Message}}});}});group.MapPut("/{id:int}",(int id,PartnerWriteRequest request,PartnerService service,CancellationToken ct)=>Save(id,request,service,ct));return endpoints;}
}
